// Emits abis/index.ts from packages/contracts/out: `runSchedule`, plus every custom error a run can revert with, so
// the keeper reports a revert by name. packages/contracts/out is not committed, so the generated file is. Rerun
// after `forge build`.

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const OUT = join(import.meta.dirname, "..", "..", "contracts", "out");
const TARGET = join(import.meta.dirname, "..", "abis", "index.ts");
/** A run pays through the account, the token, the invoice and the pool. */
const ARTIFACTS = ["CanvasAccount", "ZUSDC", "ZalInvoice", "ZalFundingPool", "ZalVault"];

interface AbiItem {
  readonly type: string;
  readonly name?: string;
  readonly inputs?: readonly { readonly type: string }[];
}

const signature = (item: AbiItem) => `${item.name}(${(item.inputs ?? []).map((i) => i.type).join(",")})`;

const items = new Map<string, AbiItem>();
for (const artifact of ARTIFACTS) {
  const path = join(OUT, `${artifact}.sol`, `${artifact}.json`);
  const abi = (JSON.parse(readFileSync(path, "utf8")) as { abi?: AbiItem[] }).abi;
  if (!Array.isArray(abi)) throw new Error(`${path}: abi is not an array`);
  for (const item of abi) {
    const wanted = item.type === "error" || (artifact === "CanvasAccount" && item.type === "function" && item.name === "runSchedule");
    if (wanted) items.set(signature(item), item);
  }
}
if (![...items.keys()].some((s) => s.startsWith("runSchedule("))) throw new Error("CanvasAccount has no runSchedule");

writeFileSync(
  TARGET,
  `// Generated by scripts/gen-abis.ts from packages/contracts/out. Do not edit.\n\nexport const keeperAbi = ${JSON.stringify([...items.values()], null, 2)} as const;\n`,
);
console.log(`wrote ${TARGET} (${items.size} items)`);
